class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        @lru_cache(None)
        def dp(v: int) -> int:
            if v <= y:
                return y - v

            ans = v - y

            for d in (5, 11):
                r = v % d
                if r == 0:
                    ans = min(ans, 1 + dp(v // d))
                else:
                    if v // d >= 1:
                        ans = min(ans, r + 1 + dp(v // d))
                    ans = min(ans, (d - r) + 1 + dp(v // d + 1))

