class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n = len(nums)
        m = len(changeIndices)

        def can(t: int) -> bool:
            last = [-1] * n

            for i in range(t):
                last[changeIndices[i] - 1] = i

            for pos in last:
                if pos == -1:
                    return False

            available = 0

            for i in range(t):
                idx = changeIndices[i] - 1

                if i == last[idx]:
                    if nums[idx] > available:
                        return False
                    available -= nums[idx]
                else:
                    available += 1

            return True

        left, right = 1, m
        answer = -1

        while left <= right:
            mid = (left + right) // 2

            if can(mid):
                answer = mid
                right = mid - 1
            else:
                left = mid + 1

        return answer
