import heapq


def solve():
    input = sys.stdin.buffer.readline

    N, M = map(int, input().split())
    incoming = [[] for _ in range(N + 1)]

    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        incoming[B].append((A, l, d, k, c))

    INF = 10**30
    dp = [-1] * (N + 1)
    dp[N] = INF

    finalized = [False] * (N + 1)
    heap = [(-INF, N)]

    while heap:
        neg_time, v = heapq.heappop(heap)

        if finalized[v]:
            continue

        time = -neg_time
        if time != dp[v]:
            continue

        finalized[v] = True

        for u, l, d, k, c in incoming[v]:
            if finalized[u]:
                continue

            limit = time - c
            if limit < l:
                continue

            q = (limit - l) // d
            if q >= k:
                q = k - 1

            departure_time = l + q * d

            if departure_time > dp[u]:
                dp[u] = departure_time
                heapq.heappush(heap, (-departure_time, u))

    answers = []
    for i in range(1, N):
        if dp[i] >= 0:
            answers.append(str(dp[i]))
        else:
            answers.append("Unreachable")

