class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)

        if k == 26:
            return 1

        vals = [ord(ch) - ord('a') for ch in s]

        # next_pos[i][c] = first position >= i containing character c, or n
        next_pos = [[n] * 26 for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            next_pos[i] = next_pos[i + 1].copy()
            next_pos[i][vals[i]] = i

        # part[i] = number of partitions for s[i:] starting fresh
        part = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            positions = [next_pos[i][c] for c in range(26) if next_pos[i][c] < n]
            if len(positions) > k:
                positions.sort()
                q = positions[k]
                part[i] = 1 + part[q]
            else:
                part[i] = 1

        # Precompute the greedy state before each index for the original string.
        pre_mask = [0] * n
        pre_parts = [0] * n

        mask = 0
        parts = 0

        for i in range(n):
            pre_mask[i] = mask
            pre_parts[i] = parts

            bit = 1 << vals[i]
            if mask & bit:
                continue

            if mask.bit_count() == k:
                parts += 1
                mask = bit
            else:
                mask |= bit

        def extra(p: int, current_mask: int) -> int:
            if p >= n:
                return 1 if current_mask else 0

            allowed = k - current_mask.bit_count()
            row = next_pos[p]

            positions = []
            for c in range(26):
                if (current_mask >> c) & 1:
                    continue
                if row[c] < n:
                    positions.append(row[c])

            if len(positions) <= allowed:
                return 1

            positions.sort()
            q = positions[allowed]
            return 1 + part[q]

        answer = 0

        for i in range(n):
            pm = pre_mask[i]
            pp = pre_parts[i]
            distinct_count = pm.bit_count()

            for c in range(26):
                bit = 1 << c

                if pm & bit:
                    new_mask = pm
                    new_parts = pp
                else:
                    if distinct_count == k:
                        new_parts = pp + 1
                        new_mask = bit
                    else:
                        new_parts = pp
                        new_mask = pm | bit

                total = new_parts + extra(i + 1, new_mask)
                if total > answer:
                    answer = total

        return answer
